#pragma once
static uint32_t ds_hash(const ds_bank *b){const uint8_t *p=(const uint8_t *)b->pattern;uint32_t h=2166136261u^b->index;for(unsigned i=0;i<sizeof b->pattern;i++)h=(h^p[i])*16777619u;return h;}
static int ds_valid(const ds_bank *b){if(b->magic!=DS_MAGIC||b->index>=8||b->checksum!=ds_hash(b))return 0;for(int p=0;p<2;p++){const ds_pattern *q=&b->pattern[p];if(q->drums>1||!q->repeats||q->repeats>16||q->next>16||q->reserved)return 0;for(int t=0;t<4;t++){const ds_track *r=&q->track[t];if(!r->length||r->length>128||(r->grid!=3&&r->grid!=4)||r->mute>1||r->reserved)return 0;for(int s=0;s<128;s++){const ds_step *x=&r->step[s];if(!x->velocity||x->velocity>127||!x->length||x->length>228||x->condition>6)return 0;if(x->condition==DS_CHANCE&&x->value>100)return 0;if(x->condition==DS_EVERY&&(x->value>>4)>(x->value&15))return 0;}}for(int s=0;s<128;s++)if(q->hits[s]>2047)return 0;}return 1;}
static void ds_stage(int bank){ds_work.magic=DS_MAGIC;ds_work.index=(uint32_t)bank;for(int j=0;j<2;j++)memcpy(&ds_work.pattern[j],ds_pattern_at(bank*2+j),sizeof(ds_pattern));ds_work.checksum=ds_hash(&ds_work);ds_claim=0;__asm__ volatile("":::"memory");ds_io=bank;}
static void d_seq_service(void){int ack=ds_ack;if(!ack)return;ds_ack=0;ds_io=-1;ds_claim=0;if(ack<0){ds.error=1;ds.saving=-1;return;}if(++ds.saving==8){ds.saving=-1;return;}ds_stage(ds.saving);}
static int ds_import(int bank){if(ds.playing||ds.saving>=0||bank<0||bank>=8||ds_work.index!=(uint32_t)bank||!ds_valid(&ds_work))return 0;for(int j=0;j<2;j++)memcpy(ds_pattern_at(bank*2+j),&ds_work.pattern[j],sizeof(ds_pattern));ds.revision++;return 1;}
static void d_seq_init(void){memset(&ds,0,sizeof ds);ds.saving=-1;ds.rng=0x58a4f123u;ds_io=-1;ds_claim=ds_ack=0;for(int p=0;p<16;p++){ds_pattern *q=ds_pattern_at(p);memset(q,0,sizeof *q);q->repeats=1;q->next=(uint8_t)p;for(int t=0;t<4;t++){q->track[t].length=16;q->track[t].grid=4;for(int s=0;s<128;s++){ds_step *x=&q->track[t].step[s];for(int n=0;n<4;n++)x->note[n]=(uint8_t)(128+60+n*3);x->velocity=100;x->length=100;x->value=50;}}}d_drum_clear();}
static void ds_release_track(int track){memset(dp[track].held[DS_SOURCE],0,128);memset(dp[track].sustained[DS_SOURCE],0,128);dp[track].pedal[DS_SOURCE]=0;d_release_slots(&dp[track]);if(track==3)for(int i=0;i<11;i++)if(d_drum_voice[i].source==DS_SOURCE)d_drum_voice[i].release=1;memset(ds.off[track],0,sizeof ds.off[track]);}
static void d_seq_stop(void){for(int t=0;t<4;t++)ds_release_track(t);ds.playing=0;ds.phase=0;ds.sub=0;}
static uint32_t ds_span(void){ds_pattern *p=ds_pattern_at(ds.pattern);uint32_t longest=1;for(int t=0;t<4;t++){uint32_t n=p->track[t].length*(p->track[t].grid==3?32u:24u);if(n>longest)longest=n;}return longest;}
static int ds_condition(const ds_step *s,int track){switch(s->condition){case DS_EVERY:{int n=(s->value&15)+1;return ds.loop[track]%(uint32_t)n==(s->value>>4);}case DS_CHANCE:ds.rng^=ds.rng<<13;ds.rng^=ds.rng>>17;ds.rng^=ds.rng<<5;return ds.rng%100u<s->value;case DS_TRIG:return ds.trig;case DS_NOT_TRIG:return !ds.trig;case DS_FILL:return ds.fill;case DS_NOT_FILL:return !ds.fill;default:return 1;}}
static void ds_note(int track,int note,int velocity,uint32_t duration){d_note_on(track,note,velocity,DS_SOURCE);if(!(track==3&&d_seq_is_drum()))dp[track].held[DS_SOURCE][note]=1;ds.off[track][note]=ds.tick+duration;if(!ds.off[track][note])ds.off[track][note]=1;}
static void ds_emit(int t){ds_pattern *p=ds_pattern_at(ds.pattern);ds_track *track=&p->track[t];uint32_t step=ds.step[t]%track->length,unit=track->grid==3?32u:24u;ds.play[t]=step;ds_step *s=&track->step[step];if(!track->mute&&ds_condition(s,t)){uint32_t duration=s->length<=100?(unit*s->length+50)/100:unit*(s->length-100);if(!duration)duration=1;if(t==3&&p->drums){uint16_t hits=p->hits[step];for(int pad=0;pad<11;pad++)if(hits&(1u<<pad))ds_note(3,d_drum_keys[pad],s->velocity,duration);}else for(int n=0;n<4;n++)if(!(s->note[n]&128))ds_note(t,s->note[n],s->velocity,duration);}ds.step[t]=(step+1)%track->length;if(!ds.step[t])ds.loop[t]++;ds.due[t]=ds.tick+unit;}
static void ds_begin(void){ds.started=1;ds.elapsed=ds.repeat=0;for(int t=0;t<4;t++){ds.step[t]=ds.loop[t]=0;ds_emit(t);}}
static void ds_change(int pattern){int was=ds.playing,old_drums=d_seq_is_drum();for(int t=0;t<4;t++)ds_release_track(t);if(old_drums!=ds_pattern_at(pattern)->drums){d_panic_part(&dp[3]);d_drum_clear();}ds.pattern=(uint8_t)pattern;ds.tick=ds.phase=ds.elapsed=ds.repeat=0;ds.started=0;ds.sub=0;for(int t=0;t<4;t++)ds.step[t]=ds.play[t]=ds.loop[t]=ds.due[t]=0;if(was)ds_begin();}
static void ds_tick(void){if(!ds.playing)return;if(!ds.started){ds_begin();return;}ds.tick++;for(int t=0;t<4;t++)for(int n=0;n<128;n++)if(ds.off[t][n]&&(int32_t)(ds.tick-ds.off[t][n])>=0){d_note_off(t,n,DS_SOURCE);ds.off[t][n]=0;}
 if(++ds.elapsed>=ds_span()){ds.elapsed=0;ds_pattern *p=ds_pattern_at(ds.pattern);if(++ds.repeat>=p->repeats){ds.repeat=0;if(p->next==DS_STOP){d_seq_stop();return;}if(p->next!=ds.pattern){ds_change(p->next);return;}}}
 for(int t=0;t<4;t++)if((int32_t)(ds.tick-ds.due[t])>=0)ds_emit(t);
}
static void d_seq_clock_pulse(void){ds.pulses++;if(!ds.playing)return;if(!ds.external){ds.external=1;ds.sub=0;if(!ds.started)ds_begin();return;}while(ds.sub<4&&ds.playing){ds_tick();ds.sub++;}ds.sub=0;}
static void d_seq_sample(void){if(!ds.playing)return;int ext=d_clock_mode==D_CLK_EXT||d_clock_external();if(ext){if(!d_clock_live())return;if(!ds.external){ds.external=1;ds.sub=0;if(!ds.started)ds_begin();}uint32_t elapsed=d_frame-d_clock_last,target=elapsed*4u/d_clock_period;if(target>3)target=3;while(ds.sub<target&&ds.playing){ds_tick();ds.sub++;}return;}if(ds.external){ds.external=0;ds.phase=0;}if(!ds.started)ds_begin();ds.phase+=(uint32_t)dg[G_TEMPO]*96u;if(ds.phase>=D_FS*60u){ds.phase-=D_FS*60u;ds_tick();}}
static void d_seq_midi_transport(int st,int source){if(source<0||source>1||d_clock_mode==D_CLK_INT||(d_clock_source>=0&&d_clock_source!=source&&d_clock_live()))return;if(st==0xfa)d_seq_control(DS_PLAY,0,0,0);else if(st==0xfb)d_seq_control(DS_CONTINUE,0,0,0);else if(st==0xfc)d_seq_stop();}
static void d_seq_control(int action,int value,int step,int track){switch(action){case DS_PLAY:if(ds.saving>=0)return;d_seq_stop();ds.tick=ds.elapsed=ds.repeat=ds.phase=0;ds.started=ds.external=0;ds.playing=1;ds.rng=0x58a4f123u;if(d_clock_mode!=D_CLK_EXT&&!d_clock_external())ds_begin();break;case DS_CONTINUE:if(ds.saving<0)ds.playing=1;break;case DS_PAUSE:d_seq_stop();break;case DS_TOGGLE:if(ds.playing)d_seq_stop();else d_seq_control(DS_PLAY,0,0,0);break;case DS_PATTERN:if(ds.saving<0&&value>=0&&value<16)ds_change(value);break;case DS_SET_FILL:ds.fill=!!value;break;case DS_SET_TRIG:ds.trig=!!value;break;case DS_SAVE:if(!ds.playing&&ds.saving<0){ds.error=0;ds.saving=0;ds_stage(0);}break;case DS_CLEAR:if(ds.saving<0&&track>=0&&track<4&&step>=0&&step<128){ds_pattern *p=ds_pattern_at(ds.pattern);for(int n=0;n<4;n++)p->track[track].step[step].note[n]|=128;if(track==3)p->hits[step]=0;ds.revision++;}break;}}
static void d_seq_edit(int pattern,int packed,int value,int note){if(pattern<0||pattern>=16||ds.saving>=0)return;int t=(packed>>12)&3,s=(packed>>4)&127,f=packed&15;ds_pattern *p=ds_pattern_at(pattern);ds_track *track=&p->track[t];ds_step *step=&track->step[s];switch(f){case DS_KEY:if(t==3&&p->drums){int pad=d_drum_pad(value);if(pad<0)return;p->hits[s]^=1u<<pad;}else{int found=-1,free=-1;for(int n=0;n<4;n++){if(!(step->note[n]&128)&&step->note[n]==value)found=n;if((step->note[n]&128)&&free<0)free=n;}if(found>=0)step->note[found]|=128;else if(free>=0&&value>=0&&value<128)step->note[free]=(uint8_t)value;else return;}break;case DS_NOTE:if(note>=0&&note<4)step->note[note]=(uint8_t)((step->note[note]&128)|dc(value,0,127));break;case DS_ON:if(t==3&&p->drums){if(note>=0&&note<11){if(value)p->hits[s]|=1u<<note;else p->hits[s]&=~(1u<<note);}}else if(note>=0&&note<4)step->note[note]=(uint8_t)((step->note[note]&127)|(value?0:128));break;case DS_HITS:if(t==3)p->hits[s]=(uint16_t)dc(value,0,2047);break;case DS_VEL:step->velocity=(uint8_t)dc(value,1,127);break;case DS_LENGTH:step->length=(uint8_t)dc(value,1,228);break;case DS_COND:step->condition=(uint8_t)dc(value,0,6);step->value=step->condition==DS_CHANCE?50:0;break;case DS_VALUE:if(step->condition==DS_CHANCE)step->value=(uint8_t)dc(value,0,100);else if(step->condition==DS_EVERY){int n=dc(value,1,16),phase=step->value>>4;if(phase>=n)phase=n-1;step->value=(uint8_t)((phase<<4)|(n-1));}break;case DS_PHASE:if(step->condition==DS_EVERY)step->value=(uint8_t)((dc(value,1,(step->value&15)+1)-1)<<4)|(step->value&15);break;case DS_TRACK_LENGTH:track->length=(uint8_t)dc(value,1,128);break;case DS_GRID:track->grid=(uint8_t)dc(value,3,4);break;case DS_DRUM:if(t==3&&p->drums!=!!value){if(pattern==ds.pattern){ds_release_track(3);d_panic_part(&dp[3]);d_drum_clear();}p->drums=!!value;}break;case DS_NEXT:p->next=(uint8_t)dc(value,0,16);break;case DS_REPEAT:p->repeats=(uint8_t)dc(value,1,16);break;case DS_MUTE:track->mute=!!value;if(pattern==ds.pattern&&track->mute)ds_release_track(t);break;default:return;}ds.revision++;}
